import 'package:flutter/material.dart';import 'package:top_snackbar_flutter/custom_snack_bar.dart';import 'package:top_snackbar_flutter/top_snack_bar.dart';import 'package:translator/translator.dart';import 'package:zan/Config/Cubit/translator_model.dart';void showSnackBar(BuildContext context, String message) {  ScaffoldMessenger.of(context).showSnackBar(    SnackBar(      padding: const EdgeInsets.all(20),      shape: const ContinuousRectangleBorder(        borderRadius: BorderRadius.all(Radius.circular(10)),      ),      content: Stack(        children: [          // BackdropFilter(          //   filter: ImageFilter.blur(sigmaX: 10.0, sigmaY: 10.0),          //   child: Container(          //     color: Colors.black,          //   ),          // ),          Column(            crossAxisAlignment: CrossAxisAlignment.start,            children: [              Text(                message, // style: Styles.textStyle20.copyWith(color: Colors.white),              ),            ],          ),        ],      ),      // backgroundColor: Colors.transparent,      elevation: 8.0,      behavior: SnackBarBehavior.fixed,    ),  );}enum SnackBarType { success, error, info }Future<void> showCustomSnackBar(  BuildContext context,  String text,  SnackBarType type, {  double iconPositionTop = 30,}) async {  CustomSnackBar customSnackBar;  String message = await (text).translateText(context);  switch (type) {    case SnackBarType.success:      customSnackBar = CustomSnackBar.success(        iconPositionTop: iconPositionTop,        message: message,      );      break;    case SnackBarType.error:      customSnackBar = CustomSnackBar.error(        message: message,        iconPositionTop: iconPositionTop,      );      break;    case SnackBarType.info:      customSnackBar = CustomSnackBar.info(        message: message,        iconPositionTop: iconPositionTop,      );      break;  }  showTopSnackBar(Overlay.of(context), customSnackBar);}